//! Stride-aware parallel splitting for GGA evaluations.
//!
//! GENERATED by tools/translate_rayon/gen_eval.py -- do not hand-edit.
//!
//! Each array carries its own elements-per-grid-point count (`Dimensions`), so
//! a run of `n` grid points sits at a *different* offset in every array.
//! Splitting them all at one offset compiles fine and silently misaligns every
//! output past the first chunk, so each is split at its own stride.
//!
//! The split is recursive halving through `rayon::join`, which keeps it in safe
//! code: each worker gets genuinely disjoint `&mut` slices, with no raw
//! pointers anywhere.

use libxc_core::dims::Dimensions;

/// One contiguous run of grid points, every array narrowed to it.
pub struct GgaChunk<'a> {
    pub np: usize,
    pub rho: &'a [f64],
    pub sigma: &'a [f64],
    pub zk: Option<&'a mut [f64]>,
    pub vrho: Option<&'a mut [f64]>,
    pub vsigma: Option<&'a mut [f64]>,
    pub v2rho2: Option<&'a mut [f64]>,
    pub v2rhosigma: Option<&'a mut [f64]>,
    pub v2sigma2: Option<&'a mut [f64]>,
    pub v3rho3: Option<&'a mut [f64]>,
    pub v3rho2sigma: Option<&'a mut [f64]>,
    pub v3rhosigma2: Option<&'a mut [f64]>,
    pub v3sigma3: Option<&'a mut [f64]>,
    pub v4rho4: Option<&'a mut [f64]>,
    pub v4rho3sigma: Option<&'a mut [f64]>,
    pub v4rho2sigma2: Option<&'a mut [f64]>,
    pub v4rhosigma3: Option<&'a mut [f64]>,
    pub v4sigma4: Option<&'a mut [f64]>,
}

#[inline]
fn split_opt(o: Option<&mut [f64]>, at: usize) -> (Option<&mut [f64]>, Option<&mut [f64]>) {
    match o {
        Some(s) => {
            let (l, r) = s.split_at_mut(at);
            (Some(l), Some(r))
        }
        None => (None, None),
    }
}

impl<'a> GgaChunk<'a> {
    /// Split at grid point `mid`, narrowing every array at its own stride.
    pub fn split_at(self, mid: usize, d: &Dimensions) -> (GgaChunk<'a>, GgaChunk<'a>) {
        let (rho_l, rho_r) = self.rho.split_at(mid * d.rho as usize);
        let (sigma_l, sigma_r) = self.sigma.split_at(mid * d.sigma as usize);
        let (o0_l, o0_r) = split_opt(self.zk, mid * d.zk as usize);
        let (o1_l, o1_r) = split_opt(self.vrho, mid * d.vrho as usize);
        let (o2_l, o2_r) = split_opt(self.vsigma, mid * d.vsigma as usize);
        let (o3_l, o3_r) = split_opt(self.v2rho2, mid * d.v2rho2 as usize);
        let (o4_l, o4_r) = split_opt(self.v2rhosigma, mid * d.v2rhosigma as usize);
        let (o5_l, o5_r) = split_opt(self.v2sigma2, mid * d.v2sigma2 as usize);
        let (o6_l, o6_r) = split_opt(self.v3rho3, mid * d.v3rho3 as usize);
        let (o7_l, o7_r) = split_opt(self.v3rho2sigma, mid * d.v3rho2sigma as usize);
        let (o8_l, o8_r) = split_opt(self.v3rhosigma2, mid * d.v3rhosigma2 as usize);
        let (o9_l, o9_r) = split_opt(self.v3sigma3, mid * d.v3sigma3 as usize);
        let (o10_l, o10_r) = split_opt(self.v4rho4, mid * d.v4rho4 as usize);
        let (o11_l, o11_r) = split_opt(self.v4rho3sigma, mid * d.v4rho3sigma as usize);
        let (o12_l, o12_r) = split_opt(self.v4rho2sigma2, mid * d.v4rho2sigma2 as usize);
        let (o13_l, o13_r) = split_opt(self.v4rhosigma3, mid * d.v4rhosigma3 as usize);
        let (o14_l, o14_r) = split_opt(self.v4sigma4, mid * d.v4sigma4 as usize);
        (
            GgaChunk {
                np: mid,
                rho: rho_l,
                sigma: sigma_l,
                zk: o0_l,
                vrho: o1_l,
                vsigma: o2_l,
                v2rho2: o3_l,
                v2rhosigma: o4_l,
                v2sigma2: o5_l,
                v3rho3: o6_l,
                v3rho2sigma: o7_l,
                v3rhosigma2: o8_l,
                v3sigma3: o9_l,
                v4rho4: o10_l,
                v4rho3sigma: o11_l,
                v4rho2sigma2: o12_l,
                v4rhosigma3: o13_l,
                v4sigma4: o14_l,
            },
            GgaChunk {
                np: self.np - mid,
                rho: rho_r,
                sigma: sigma_r,
                zk: o0_r,
                vrho: o1_r,
                vsigma: o2_r,
                v2rho2: o3_r,
                v2rhosigma: o4_r,
                v2sigma2: o5_r,
                v3rho3: o6_r,
                v3rho2sigma: o7_r,
                v3rhosigma2: o8_r,
                v3sigma3: o9_r,
                v4rho4: o10_r,
                v4rho3sigma: o11_r,
                v4rho2sigma2: o12_r,
                v4rhosigma3: o13_r,
                v4sigma4: o14_r,
            },
        )
    }
}

use std::sync::atomic::{AtomicUsize, Ordering};

/// Minimum grid points per task; below this, splitting costs more than it saves.
static MIN_CHUNK: AtomicUsize = AtomicUsize::new(2048);

pub fn min_chunk() -> usize {
    MIN_CHUNK.load(Ordering::Relaxed)
}

/// Test hook. Setting this to `usize::MAX` disables splitting, so a dispatch
/// runs as one whole-grid call -- which is exactly the reference the chunked
/// path has to reproduce bit-for-bit.
pub fn set_min_chunk(n: usize) {
    MIN_CHUNK.store(n.max(1), Ordering::Relaxed);
}

/// Recursively halve the grid and evaluate each piece in parallel.
pub fn par_sweep<F>(chunk: GgaChunk<'_>, d: &Dimensions, min_chunk: usize, f: &F)
where
    F: Fn(GgaChunk<'_>) + Sync,
{
    if chunk.np <= min_chunk {
        f(chunk);
        return;
    }
    let mid = chunk.np / 2;
    let (l, r) = chunk.split_at(mid, d);
    rayon::join(
        || par_sweep(l, d, min_chunk, f),
        || par_sweep(r, d, min_chunk, f),
    );
}
